import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
m = int(data[1])

A = []
B = []

index = 2
for i in range(n):
    A.append(list(map(int, data[index:index + m])))
    index += m

for i in range(n):
    B.append(list(map(int, data[index:index + m])))
    index += m

def is_sorted_by_column(table, col):
    return all(table[i][col] <= table[i + 1][col] for i in range(n - 1))

def find_sort_sequence(A, B):
    if A == B:
        return [0]

    for col in range(m):
        if is_sorted_by_column(A, col):
            continue
        sorted_A = sorted(enumerate(A), key=lambda x: x[1][col])
        new_A = [A[i] for i, _ in sorted_A]
        result = find_sort_sequence(new_A, B)
        if result != -1:
            return [col + 1] + result
    return -1

result = find_sort_sequence(A, B)
if result == -1:
    print(-1)
else:
    print(len(result))
    print(' '.join(map(str, result)))
